package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.ActivityController;
import java.util.*;import java.lang.reflect.*;import java.security.*;import org.json.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)
@Config(sdk=28,application=android.app.Application.class)
public class ListControlsTest {
 public static class FakeMain extends MainActivity {protected ScApi createApi(){return new ScApi(this){public Page likes(String user,String next)throws Exception{ScApi.Page p=LibraryPagerTest.page(next.isEmpty()?0:100,next.isEmpty()?100:64,false);if(next.isEmpty())p.next="page2";return p;}public Page playlists(String user,boolean liked,String next)throws Exception{ScApi.Page p=LibraryPagerTest.page(next.isEmpty()?0:100,next.isEmpty()?100:23,true);if(next.isEmpty())p.next="page2";return p;}public ArrayList<Library.Track> playlistTracks(String id)throws Exception{return LibraryPagerTest.page(0,250,false).tracks;}};}}
 @Before public void prepare()throws Exception{Context c=RuntimeEnvironment.getApplication();c.getSharedPreferences("profile",0).edit().putString("id","123").commit();Provider provider=new Provider("VolnaSyntheticKeyStore",1.0,"test only"){};provider.put("KeyStore.AndroidKeyStore",WarmWriterTest.MemoryStore.class.getName());Security.insertProviderAt(provider,1);Session.put(c,"OAuth SYNTHETIC_LIST_TOKEN_12345","SYNTHETIC_LIST_CLIENT_12345");}
 @After public void cleanup(){Security.removeProvider("VolnaSyntheticKeyStore");}
 List<View> all(View root){List<View> result=new ArrayList<>();result.add(root);if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++)result.addAll(all(((ViewGroup)root).getChildAt(i)));return result;}
 Object field(Object object,String name)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(object);}
 ActivityController<FakeMain> screen(String filter,String playlist)throws Exception{Bundle state=new Bundle();state.putString("process",SoundFlowApplication.PROCESS);state.putString("page","library");state.putString("filter",filter);state.putString("playlistId",playlist);state.putString("playlist","Test playlist");ActivityController<FakeMain> controller=Robolectric.buildActivity(FakeMain.class).create(state);FakeMain main=controller.get();long until=System.currentTimeMillis()+6000;do{Shadows.shadowOf(Looper.getMainLooper()).idle();if(!((Boolean)field(main,"busy")))break;Thread.sleep(20);}while(System.currentTimeMillis()<until);assertFalse("Library request did not finish",(Boolean)field(main,"busy"));return controller;}
 Switch toggle(Activity a){for(View v:all(a.getWindow().getDecorView()))if(v instanceof Switch&&"Автозагрузка".contentEquals(((Switch)v).getText()))return (Switch)v;return null;}
 void noLoadMore(Activity a){for(View v:all(a.getWindow().getDecorView()))if(v instanceof TextView)assertNotEquals("Загрузить ещё",((TextView)v).getText().toString());}
 @Test public void likedListShows164AndItsOwnAutoToggle()throws Exception{ActivityController<FakeMain> controller=screen("likes","");FakeMain main=controller.get();assertEquals(164,((List<?>)field(main,"visible")).size());Switch sw=toggle(main);assertNotNull(sw);assertFalse(sw.isChecked());sw.performClick();assertTrue(sw.isChecked());assertTrue(AutoDownloads.enabled(main,"123","likes"));noLoadMore(main);controller.destroy();}
 @Test public void insidePlaylistShows250AndItsOwnAutoToggle()throws Exception{ActivityController<FakeMain> controller=screen("playlists","99");FakeMain main=controller.get();assertEquals(250,((List<?>)field(main,"visible")).size());assertNotNull(toggle(main));noLoadMore(main);controller.destroy();}
 @Test public void collectionLoadsAll123Playlists()throws Exception{ActivityController<FakeMain> controller=screen("playlists","");FakeMain main=controller.get();assertEquals(123,((List<?>)field(main,"cloudPlaylists")).size());assertNull(toggle(main));noLoadMore(main);controller.destroy();}
 @Test public void titleIsVerticallyCentered()throws Exception{ActivityController<FakeMain> controller=screen("likes","");TextView brand=null;for(View v:all(controller.get().getWindow().getDecorView()))if(v instanceof TextView&&"SoundFlow".contentEquals(((TextView)v).getText()))brand=(TextView)v;assertNull("Brand text removed from header",brand);controller.destroy();}
 @Test public void downloadsScreenHasNoAutoEnableOrAddListControl()throws Exception{Context c=RuntimeEnvironment.getApplication();try(SyncDb db=new SyncDb(c)){db.ensure("123","likes","Любимое","favorites");db.auto("123","likes",true);}ActivityController<AutoDownloadActivity> controller=Robolectric.buildActivity(AutoDownloadActivity.class).setup();Shadows.shadowOf(Looper.getMainLooper()).idle();for(View v:all(controller.get().getWindow().getDecorView()))if(v instanceof TextView){String text=((TextView)v).getText().toString();assertNotEquals("＋",text);assertNotEquals("Включить автозагрузку",text);assertNotEquals("✓ Автозагрузка включена",text);}controller.pause().stop().destroy();}
 @Test public void disablingFromLikedListAsksAndCancelPreservesEnabled()throws Exception{Context c=RuntimeEnvironment.getApplication();try(SyncDb db=new SyncDb(c)){db.ensure("123","likes","Любимое","favorites");db.auto("123","likes",true);}ActivityController<FakeMain> controller=screen("likes","");Switch sw=toggle(controller.get());assertTrue(sw.isChecked());sw.performClick();AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotNull(dialog);assertTrue(sw.isChecked());dialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertTrue(AutoDownloads.enabled(c,"123","likes"));assertTrue(sw.isChecked());sw.performClick();dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse(AutoDownloads.enabled(c,"123","likes"));assertFalse(sw.isChecked());controller.destroy();}
 @Test public void playlistToggleAffectsOnlyThatPlaylist()throws Exception{ActivityController<FakeMain> controller=screen("playlists","99");Switch sw=toggle(controller.get());sw.performClick();assertTrue(AutoDownloads.enabled(controller.get(),"123","99"));assertFalse(AutoDownloads.enabled(controller.get(),"123","likes"));controller.destroy();}

}
